  (15, 'rebecca-website', 'Rebecca Website', 'Site institucional/pessoal de Rebecca Lucena Campos de Souza — pesquisadora. Perfil acadêmico, portfolio de pesquisas, publicações científicas, dashboard de emissões de CO₂, área administrativa com autenticação JWT. Stack: React 19 + Go 1.24 (Gin) + MySQL. Porta 8082 (dev). v0.1.0 — Alpha.', 'planning', 'rebecca-website', '/root/projetos/itscwf/rebecca-website', NULL, NULL, NULL, 0, '2026-09-15T15:59:49Z', '2026-09-15T17:06:12Z', NULL),
  (16, 'small-ngo', 'Small NGO', 'Sistema de gestao para ONGs (doacoes, voluntarios, beneficiarios, certificacoes, grants). Backend Go (Fiber v2) + GORM, frontend React 18 + TypeScript + Vite + TailwindCSS. Copia seletiva de estrutura/logica do smallcrm v2. Porta backend 8081/8085, frontend 3002, MySQL 3307.', 'active', 'small-ngo', '/root/projetos/itscwf/small-ngo', 'git@github.com:itscwf/smallngo.git', NULL, NULL, 0, '2026-09-15T15:59:49Z', '2026-09-15T17:06:12Z', NULL),
