  (18, 'smallcrm-dashboard', 'smallcrm-dashboard', NULL, 'active', NULL, '/root/projetos/itscwf/smallcrm-dashboard', 'git@github.com:itscwf/smallcrm-dashboard.git', NULL, NULL, 0, '2026-09-15T15:59:49Z', '2026-09-15T17:06:12Z', NULL),
  (19, 'smallcrm-dashboard-v2', 'SmallCRM Dashboard v2', 'CRM multi-tenant moderno — reescrita completa do SmallCRM original. Backend Go (Fiber v2) + Frontend React 18. Pipeline Kanban drag-and-drop, booking com Google Calendar/Microsoft 365, gestão de leads/clientes/oportunidades/propostas, organograma hierárquico, round-robin de leads, rate limiting multi-lane, monitoria Prometheus + Grafana. Porta 8082 (dev), ghcr.io/itscwf/ para imagens. v2.0.0 — produção-ready.', 'active', 'smallcrm-dashboard-v2', '/root/projetos/itscwf/smallcrm-dashboard-v2', 'git@github.com:itscwf/smallcrm-dashboard-v2.git', NULL, NULL, 0, '2026-09-15T15:59:50Z', '2026-09-15T17:06:12Z', NULL),
